import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Extracts — Advanced Features & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"extracts-03-advanced-and-customization.md","filePath":"extracts-03-advanced-and-customization.md"}'),i={name:"extracts-03-advanced-and-customization.md"};function o(r,e,l,c,d,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="extracts-—-advanced-features-customization" tabindex="-1">Extracts — Advanced Features &amp; Customization <a class="header-anchor" href="#extracts-—-advanced-features-customization" aria-label="Permalink to &quot;Extracts — Advanced Features &amp; Customization&quot;">​</a></h1><p><em>Integrations, transcript strategy, and getting the most from the AI</em></p><hr><h2 id="the-fireflies-and-gong-integrations" tabindex="-1">The Fireflies and Gong Integrations <a class="header-anchor" href="#the-fireflies-and-gong-integrations" aria-label="Permalink to &quot;The Fireflies and Gong Integrations&quot;">​</a></h2><p>Fireflies and Gong are both live integrations for the Extracts module. Rather than manually downloading transcripts and uploading them to Lodestone, both integrations let you pull meeting transcripts directly into the Extracts module in a few clicks.</p><h3 id="how-lodestone-and-these-tools-divide-responsibilities" tabindex="-1">How Lodestone and these tools divide responsibilities <a class="header-anchor" href="#how-lodestone-and-these-tools-divide-responsibilities" aria-label="Permalink to &quot;How Lodestone and these tools divide responsibilities&quot;">​</a></h3><p>Fireflies and Gong are the sources of truth for transcripts — they handle recording, transcription, and storage. Lodestone is the analysis and planning layer — it reads the transcript, surfaces ideas, and connects them to your planning workflow. Neither tool is replaced by the other.</p><h3 id="fireflies-access-scope" tabindex="-1">Fireflies access scope <a class="header-anchor" href="#fireflies-access-scope" aria-label="Permalink to &quot;Fireflies access scope&quot;">​</a></h3><p>When importing from Fireflies, any meeting in your connected Fireflies instance is accessible for import.</p><h3 id="gong-access-scope" tabindex="-1">Gong access scope <a class="header-anchor" href="#gong-access-scope" aria-label="Permalink to &quot;Gong access scope&quot;">​</a></h3><p>When you first connect the Gong integration, you&#39;re prompted to select which Gong accounts to pull transcripts from. This allows you to scope the integration to your front-line customer-facing colleagues — such as AEs, CSMs, or SDRs — rather than ingesting every call across the organization.</p><p>See the Integrations module guide for full setup instructions for both integrations.</p><hr><h2 id="planned-integrations" tabindex="-1">Planned Integrations <a class="header-anchor" href="#planned-integrations" aria-label="Permalink to &quot;Planned Integrations&quot;">​</a></h2><p>Beyond Fireflies and Gong, Lodestone plans to support direct transcript ingestion from:</p><ul><li>Salesforce</li><li>Zendesk</li><li>Freshdesk</li><li>Other CRM and support systems</li></ul><p>When these integrations ship, Extracts will expand further into an organization-wide listening system — automatically ingesting signals from sales, support, and customer success without requiring any manual upload.</p><hr><h2 id="getting-better-extracts-from-your-transcripts" tabindex="-1">Getting Better Extracts from Your Transcripts <a class="header-anchor" href="#getting-better-extracts-from-your-transcripts" aria-label="Permalink to &quot;Getting Better Extracts from Your Transcripts&quot;">​</a></h2><p>The quality of Extracts depends heavily on the quality of the transcript. A few things that improve output:</p><p>One of the most powerful ways to use Extracts is to look for patterns across multiple transcripts rather than acting on each Extract in isolation.</p><p>If the same problem or request surfaces in three different customer conversations, that&#39;s a signal worth paying attention to — even if no single Extract seemed urgent on its own. Strong PMs review Extracts in batches and use them to spot themes before deciding what to promote.</p><p>This approach works especially well when you&#39;re running a discovery sprint or synthesizing input from a round of customer interviews.</p><hr><h2 id="planned-integrations-1" tabindex="-1">Planned Integrations <a class="header-anchor" href="#planned-integrations-1" aria-label="Permalink to &quot;Planned Integrations&quot;">​</a></h2><p>Beyond Fireflies and Gong, Lodestone plans to support direct transcript ingestion from:</p><ul><li>Salesforce</li><li>Zendesk</li><li>Freshdesk</li><li>Other CRM and support systems</li></ul><p>When these integrations ship, Extracts will expand further into an organization-wide listening system — automatically ingesting signals from sales, support, and customer success without requiring any manual upload.</p><hr><p><em>Next: Troubleshooting &amp; FAQs — common issues with transcript uploads, unexpected Extract output, and frequent questions.</em></p>',30)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
